contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        // Fund c with exactly `value` Ether so the outcome is observable via balances.
        c.sendMoney(address(c), value, ""); if (__ESBMC_reverted()) return;

        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        assert((!reverted && afterC + value == beforeC && afterSelf == beforeSelf + value) || (reverted && afterC == beforeC && afterSelf == beforeSelf));
    }

    receive() external payable {}
}

